import {blocked} from './logic.mjs';
import {generatedMap} from './generated-materials.mjs';
import * as T from './vendor/three.module.js';
export function duskAmount(v){return Math.max(0,Math.min(1,(.65-v.day)/.65));}
// Fixtures remain in the scene; only the nearest six/eight lights are evaluated.
export function createPracticalLighting(scene,{compact=false,region='alp',height=()=>0,interactive=[],paths=[],colliders=[]}={}){
 const valley=[];scene.traverse(o=>{if(o.userData.kind==='valley-day-night-panorama')valley.push(o);});const existing=[],backdrops=[],windows=[],seen=new Set(),fixtures=[];
 scene.traverse(o=>{if(o.isPointLight)existing.push({o,base:o.intensity});for(const m of Array.isArray(o.material)?o.material:o.material?[o.material]:[]){if(m.userData?.nightBackdrop&&!backdrops.includes(m))backdrops.push(m);if(!seen.has(m)&&m.userData?.nightWindow){seen.add(m);windows.push(m);}}});
 const iron=new T.MeshStandardMaterial({color:'#414038',metalness:.65,roughness:.5}),wood=new T.MeshStandardMaterial({color:'#b6a18a',map:generatedMap('home-wood-20261018'),roughness:.96});
 function fixture(x,z,y=null,parent=scene){const g=new T.Group();g.userData.kind='automatic-alpine-lantern';g.position.set(x,y??height(x,z),z);parent.add(g);const glass=new T.MeshStandardMaterial({color:'#d5c09a',emissive:'#ffbd63',emissiveIntensity:0,roughness:.24});
 const lamp=new T.Group();lamp.position.x=.55;g.add(lamp);const post=new T.Mesh(new T.CylinderGeometry(.065,.09,3.15,8),wood);post.position.set(-.35,1.575,0);post.castShadow=true;g.add(post);const hook=new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3([new T.Vector3(-.35,2.8,0),new T.Vector3(-.15,3.22,0),new T.Vector3(.46,3.34,0),new T.Vector3(.63,3.19,0),new T.Vector3(.55,3.05,0)]),16,.032,6,false),iron);g.add(hook);
 const mesh=(geo,m,a,b,c)=>{const o=new T.Mesh(geo,m);o.position.set(a,b,c);o.castShadow=true;lamp.add(o);return o;};
 mesh(new T.BoxGeometry(.38,.07,.38),iron,0,2.31,0);mesh(new T.BoxGeometry(.25,.36,.25),glass,0,2.52,0);for(const a of[-1,1])for(const b of[-1,1])mesh(new T.CylinderGeometry(.019,.019,.43,6),iron,a*.15,2.53,b*.15);const roof=mesh(new T.ConeGeometry(.32,.23,4),iron,0,2.86,0);roof.rotation.y=Math.PI/4;mesh(new T.TorusGeometry(.07,.016,6,12),iron,0,3.04,0);
 const light=new T.PointLight('#ffd39a',0,9,2);light.position.set(0,2.5,0);lamp.add(light);fixtures.push({g,light,glass});return g;}
 const indoor=['house','restaurant','arcadeshop','villageshop','danielhut','cellar','passage','kristall'].includes(region);
 if(!indoor){let sites=region==='alp'?[[-13,-2],[-1,-7],[-6,2],[-4,12],[-8,21],[22,0],[31,-10],[-23,-15]]:interactive.filter(n=>n.gateway||n.fodderShop||n.villageService).slice(0,10).map(n=>[n.x+1.4,n.z-.3]);if(region==='village')sites.push([-3,9],[7,10],[3,-1],[12,14],[-9,15]);const doors=[];scene.traverse(o=>{if(o.userData.door)doors.push(o.userData.door);});for(const d of doors)if(!sites.some(([x,z])=>Math.hypot(x-d.x,z-d.z)<3))sites.push([d.x+1.4,d.z]);for(const [x,z]of sites){const p=region==='alp'&&paths.length?lanternVerge(x,z,paths,colliders,interactive,fixtures.map(f=>f.g.position)): {x,z};if(p){const f=fixture(p.x,p.z);f.userData.requestedSite={x,z};if(region==='alp'&&paths.length)colliders.push({type:'circle',x:p.x-.35,z:p.z,r:.13,lantern:true});}}}
 if(['house','restaurant','arcadeshop','villageshop','danielhut'].includes(region)){const f=fixture(-4.3,2.8,0);f.scale.setScalar(.7);}
 // Warm floor lamps in the habitable storeys, with the same switch as wall lights.
 const floors=[];scene.traverse(o=>{if(['stube','bedroom','cellar'].includes(o.userData.floor))floors.push(o);});for(const floor of floors){const f=fixture(-4.65,2.6,0,floor);f.scale.setScalar(.78);f.traverse(o=>o.layers.mask=floor.layers.mask);}
 if(region==='alp'){const g=new T.Group();g.position.set(1.5,height(1.5,-13)+2.55,-13);g.userData.kind='barn-night-pendant';scene.add(g);const glass=new T.MeshStandardMaterial({color:'#e7d6a5',emissive:'#ffc978',emissiveIntensity:0}),shade=new T.Mesh(new T.ConeGeometry(.28,.2,12),iron);shade.position.y=.2;g.add(shade);g.add(new T.Mesh(new T.SphereGeometry(.12,12,8),glass));const light=new T.PointLight('#ffd19a',0,10);g.add(light);fixtures.push({g,light,glass});}
 const all=[...existing,...fixtures.map(f=>({o:f.light,base:12}))],wp=new T.Vector3();
 const kit={mode:'auto',fixtures,step(v,actor,inside=false){for(const o of valley){const day=o.children.find(c=>c.userData.valleyPhase==='day'),night=o.children.find(c=>c.userData.valleyPhase==='night');if(day&&night){night.material.opacity=Math.min(1,Math.max(0,(.6-v.day)/.6));night.visible=night.material.opacity>.001;day.material.color.setScalar(.65+.35*v.day);}}const amount=duskAmount(v),interiorAmount=kit.mode==='on'?1:kit.mode==='off'?0:['cellar','passage','kristall'].includes(region)?1:amount;const ranked=all.map(l=>{l.o.getWorldPosition(wp);let visible=true;for(let q=l.o.parent;q;q=q.parent)if(!q.visible)visible=false;return{...l,d:visible?wp.distanceToSquared(actor):Infinity};}).sort((a,b)=>a.d-b.d),enabled=new Set(ranked.filter(l=>l.d<32*32).slice(0,compact?6:8).map(l=>l.o));for(const l of all){let inRoom=indoor;for(let q=l.o.parent;q;q=q.parent)if(q.userData.floor)inRoom=true;const a=inRoom?interiorAmount:amount;l.o.visible=enabled.has(l.o)&&a>.001;l.o.intensity=l.o.visible?l.base*a:0;}for(const f of fixtures){let inRoom=indoor;for(let q=f.g.parent;q;q=q.parent)if(q.userData.floor)inRoom=true;f.glass.emissiveIntensity=(inRoom?interiorAmount:amount)*1.7;}for(const m of backdrops)m.color.setScalar(.18+.82*v.day);for(const m of windows){m.emissive.set('#ffc678');m.emissiveIntensity=.06+amount*.8;}}};return kit;
}

// The whole lantern footprint clears the road, including post and hanging head.
export function pathClearance(x,z,paths){let best=Infinity;for(const p of paths)for(let i=1;i<p.points.length;i++){const a=p.points[i-1],b=p.points[i],dx=b[0]-a[0],dz=b[1]-a[1],d=dx*dx+dz*dz,t=d?Math.max(0,Math.min(1,((x-a[0])*dx+(z-a[1])*dz)/d)):0;best=Math.min(best,Math.hypot(x-a[0]-t*dx,z-a[1]-t*dz)-p.width/2);}return best;}
export function lanternVerge(x,z,paths,colliders,interactive=[],placed=[]){for(let radius=0;radius<=8;radius+=.5)for(let i=0;i<(radius?24:1);i++){const a=i*Math.PI/12,xx=x+Math.cos(a)*radius,zz=z+Math.sin(a)*radius;if(pathClearance(xx,zz,paths)<1.1||blocked(xx,zz,colliders,.75)||interactive.some(p=>Math.hypot(xx-p.x,zz-p.z)<1.35)||placed.some(p=>Math.hypot(xx-p.x,zz-p.z)<2))continue;return{x:xx,z:zz};}return null;}
